#include <iostream>

class Counter {
    int count;
public:
    explicit Counter(int c = 0) : count{c} {}

    // Prefix increment: modifies state and returns *this by reference (lvalue)
    Counter &operator++() {
        ++count;
        return *this;
    }

    // Postfix increment: takes dummy int, preserves old value, returns by value (rvalue)
    Counter operator++(int) {
        Counter temp = *this;
        ++count;
        return temp;
    }

    int value() const { return count; }
};

int main() {
    Counter c1{10};
    std::cout << "Initial: " << c1.value() << '\n';

    // Prefix test
    Counter &ref = ++c1;
    std::cout << "After ++c1: " << c1.value() << ", returned ref: " << ref.value() << '\n';

    // Postfix test
    Counter old = c1++;
    std::cout << "During c1++ returned: " << old.value() << ", current c1: " << c1.value() << '\n';

    return 0;
}

#include <array>
#include <iostream>
#include <stdexcept>
#include <string>

class Date {
    friend std::ostream &operator<<(std::ostream &out, const Date &d) {
        static const std::string monthNames[13] = {
            "", "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };
        out << monthNames[d.month] << ' ' << d.day << ", " << d.year;
        return out;
    }

public:
    static constexpr std::array<unsigned int, 13> days{
        0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31
    };

    Date(int m = 1, int d = 1, int y = 1900) {
        setDate(m, d, y);
    }

    void setDate(int mm, int dd, int yy) {
        if (mm < 1 || mm > 12) {
            throw std::invalid_argument("Month must be 1-12");
        }
        if (yy < 1900 || yy > 2100) {
            throw std::invalid_argument("Year must be >= 1900 and <= 2100");
        }
        if ((mm == 2 && leapYear(yy) && dd >= 1 && dd <= 29) ||
            (dd >= 1 && dd <= static_cast<int>(days[mm]))) {
            month = static_cast<unsigned int>(mm);
            day = static_cast<unsigned int>(dd);
            year = static_cast<unsigned int>(yy);
        } else {
            throw std::invalid_argument("Day is out of range for current month and year");
        }
    }

    static bool leapYear(int testYear) {
        return (testYear % 400 == 0 || (testYear % 100 != 0 && testYear % 4 == 0));
    }

    bool endOfMonth(int testDay) const {
        if (month == 2 && leapYear(year)) {
            return testDay == 29;
        }
        return testDay == static_cast<int>(days[month]);
    }

    // Prefix increment operator
    Date &operator++() {
        helpIncrement();
        return *this;
    }

    // Postfix increment operator
    Date operator++(int) {
        Date temp = *this;
        helpIncrement();
        return temp;
    }

    // Addition assignment operator
    Date &operator+=(unsigned int additionalDays) {
        for (unsigned int i = 0; i < additionalDays; ++i) {
            helpIncrement();
        }
        return *this;
    }

private:
    unsigned int month{1};
    unsigned int day{1};
    unsigned int year{1900};

    void helpIncrement() {
        if (!endOfMonth(day)) {
            ++day;
        } else if (month < 12) {
            ++month;
            day = 1;
        } else {
            ++year;
            month = 1;
            day = 1;
        }
    }
};

int main() {
    Date d1{12, 27, 2010};
    Date d2;

    std::cout << "d1 is " << d1 << "\nd2 is " << d2 << "\n\n";

    d1 += 7;
    std::cout << "d1 += 7 is " << d1 << "\n\n";

    d2.setDate(2, 28, 2008);
    std::cout << "  d2 is " << d2 << "\n";
    std::cout << "++d2 is " << ++d2 << " (leap year allows 29th)\n\n";

    Date d3{7, 13, 2010};
    std::cout << "Testing the prefix increment operator:\n";
    std::cout << "  d3 is " << d3 << '\n';
    std::cout << "++d3 is " << ++d3 << '\n';
    std::cout << "  d3 is " << d3 << "\n\n";

    std::cout << "Testing the postfix increment operator:\n";
    std::cout << "  d3 is " << d3 << '\n';
    std::cout << "d3++ is " << d3++ << '\n';
    std::cout << "  d3 is " << d3 << '\n';

    return 0;
}
